# The right arm's current joint configuration prevents the requested wrist rotation.
# Return both arms through bounded joint interpolation to their saved starting posture before retrying the pickup.
s = get_observation()['state']
starts = {k: np.array(s[k]).copy() for k in ['left_arm_joint_state','right_arm_joint_state']}
for i in range(18):
    a = {}
    for k in starts:
        a[k] = starts[k] + min(1.0, (i+1)/15.0) * (np.array(home[k])-starts[k])
    a['left_ee_joint_state'] = [1.0]
    a['right_ee_joint_state'] = [1.0]
    obs, reward, terminated, truncated, info = step(a)
    if terminated or truncated:
        break
print(obs['state'])

