# The remaining action allowance cannot support another recovery, and the white insertion is unconfirmed.
# Release, return both arms to the saved home joints, and hold through the official final check.
s = get_observation()['state']
a = {k: s[k] for k in ['left_ee_pose','right_ee_pose']}
a['left_ee_joint_state'] = [1.0]
a['right_ee_joint_state'] = [1.0]
ended = False
for i in range(5):
    obs, reward, terminated, truncated, info = step(a)
    if terminated or truncated:
        ended = True
        break
if not ended:
    s = get_observation()['state']
    starts = {k: np.array(s[k]).copy() for k in ['left_arm_joint_state','right_arm_joint_state']}
    for i in range(28):
        a = {k: starts[k] + min(1.0, (i+1)/15.0) * (np.array(home[k])-starts[k]) for k in starts}
        a['left_ee_joint_state'] = [1.0]
        a['right_ee_joint_state'] = [1.0]
        obs, reward, terminated, truncated, info = step(a)
        if terminated or truncated:
            break
print('final', reward, terminated, truncated, info)
print(obs['state'])

